CREATE SCHEMA IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_anz;
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_anz.nem_dispatch_intervals (dispatch_interval_id BIGINT, interval_datetime TIMESTAMP, region_id STRING, rrp DECIMAL(12,4), dispatch_price DECIMAL(12,4), totaldemand DECIMAL(12,2), availablegeneration DECIMAL(12,2), netinterchange DECIMAL(12,2), lower5min DECIMAL(12,4), lower60sec DECIMAL(12,4), lower6sec DECIMAL(12,4), raise5min DECIMAL(12,4), raise60sec DECIMAL(12,4), raise6sec DECIMAL(12,4), lowerreg DECIMAL(12,4), raisereg DECIMAL(12,4), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_anz.bess_assets (duid STRING, asset_name STRING, operator STRING, region_id STRING, capacity_mw DECIMAL(10,2), duration_hours DECIMAL(5,2), technology STRING, commissioned_date DATE, status STRING, scada_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_anz.bess_telemetry (telemetry_id BIGINT, duid STRING, recorded_at TIMESTAMP, state_of_charge_pct DECIMAL(5,2), output_mw DECIMAL(10,2), fcas_raise_mw DECIMAL(10,2), fcas_lower_mw DECIMAL(10,2), available_mw DECIMAL(10,2), temperature_c DECIMAL(6,2), cycle_count_today DECIMAL(6,1), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_anz.settlement_revenues (revenue_id BIGINT, duid STRING, settlement_date DATE, trading_interval_end TIMESTAMP, energy_revenue DECIMAL(14,4), fcas_raise5min_revenue DECIMAL(14,4), fcas_lower5min_revenue DECIMAL(14,4), fcas_raise60sec_revenue DECIMAL(14,4), fcas_lower60sec_revenue DECIMAL(14,4), fcas_raise6sec_revenue DECIMAL(14,4), fcas_lower6sec_revenue DECIMAL(14,4), total_revenue DECIMAL(14,4), mlf_applied DECIMAL(8,6), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_anz.generation_portfolio (duid STRING, asset_name STRING, fuel_type STRING, region_id STRING, registered_capacity_mw DECIMAL(10,2), annual_generation_gwh DECIMAL(12,2), market_participant STRING, connection_point STRING);
